from math import comb

def ratio_multipartite(k):
    if k < 4:
        return 0

    f_term = comb(k, 3)
    g_term = comb(k, 4)

    # R(k) = g(G)^3 / f(G)^4
    return (g_term**3) / (f_term**4)

# Test k from 4 to 10
results = {}
for k in range(4, 11):
    results[k] = ratio_multipartite(k)

print(results)
